3	import java.time.Clock;
4	import java.time.Instant;
5	import java.util.List;
6	import java.util.Optional;
7	
8	import org.springframework.stereotype.Service;
9	import org.springframework.transaction.annotation.Transactional;
10	
11	import com.example.starter.maintenance.api.ApiException;
12	import com.example.starter.maintenance.api.dto.AddReadingRequest;
13	import com.example.starter.maintenance.api.dto.CompleteMaintenanceRequest;
14	import com.example.starter.maintenance.api.dto.EquipmentResponse;
15	import com.example.starter.maintenance.api.dto.MaintenanceResponse;
16	import com.example.starter.maintenance.api.dto.ReadingResponse;
17	import com.example.starter.maintenance.api.dto.RegisterEquipmentRequest;
18	import com.example.starter.maintenance.api.dto.ReviseReadingRequest;
19	import com.example.starter.maintenance.api.dto.RevisionView;
20	import com.example.starter.maintenance.api.dto.StatusResponse;
21	import com.example.starter.maintenance.domain.Equipment;
22	import com.example.starter.maintenance.domain.MaintenanceRecord;
23	import com.example.starter.maintenance.domain.Reading;
24	import com.example.starter.maintenance.store.EquipmentRepository;
25	
26	/**
27	 * 设备工时保养事务业务服务。写操作流程：设备行锁 → 幂等判定 → 版本校验 → 业务规则 → 变更并版本加一。
28	 * 去重记录与业务变更同事务提交；任一规则失败抛异常整体回滚。
29	 */
30	@Service
31	public class EquipmentTxService {
32	
33	    private final EquipmentRepository repository;
34	    private final IdempotencyService idempotency;
35	    private final Clock clock;
36	
37	    public EquipmentTxService(EquipmentRepository repository, IdempotencyService idempotency, Clock clock) {
38	        this.repository = repository;
39	        this.idempotency = idempotency;
40	        this.clock = clock;
41	    }
42	
43	    // ---------- 登记设备 ----------
44	
45	    @Transactional
46	    public EquipmentResponse register(RegisterEquipmentRequest req) {
47	        String fingerprint = req.equipmentId() + "|" + req.maintenancePeriodMinutes();
48	        return idempotency.execute(req.requestId(), "REGISTER_EQUIPMENT", fingerprint,
49	                EquipmentResponse.class, () -> {
50	                    if (repository.findEquipment(req.equipmentId()).isPresent()) {
51	                        throw ApiException.conflict("EQUIPMENT_EXISTS", "设备已存在：" + req.equipmentId());
52	                    }
53	                    repository.insertEquipment(req.equipmentId(), req.maintenancePeriodMinutes(), clock.instant());
54	                    return new EquipmentResponse(req.equipmentId(), req.maintenancePeriodMinutes(), 1L);
55	                });
56	    }
57	
58	    // ---------- 新增读数 ----------
59	
60	    @Transactional
61	    public ReadingResponse addReading(String equipmentId, AddReadingRequest req) {
62	        Equipment equipment = lockEquipment(equipmentId);
63	        String fingerprint = equipmentId + "|" + req.readingId() + "|" + req.sampledAt()
64	                + "|" + req.cumulativeMinutes() + "|" + req.expectedVersion();
65	        return idempotency.execute(req.requestId(), "ADD_READING", fingerprint,
66	                ReadingResponse.class, () -> {
67	                    checkVersion(equipment, req.expectedVersion());
68	                    if (repository.findReading(equipmentId, req.readingId()).isPresent()) {
69	                        throw ApiException.conflict("READING_EXISTS", "读数已存在：" + req.readingId());
70	                    }
71	                    if (repository.findReadingAt(equipmentId, req.sampledAt()).isPresent()) {
72	                        throw ApiException.unprocessable("READING_TIME_DUPLICATE",
73	                                "同一设备同一采样时刻仅允许一条读数");
74	                    }
75	                    checkMonotonic(equipmentId, req.sampledAt(), req.cumulativeMinutes());
76	                    Instant now = clock.instant();
77	                    repository.insertReading(
78	                            new Reading(equipmentId, req.readingId(), req.sampledAt(),
79	                                    req.cumulativeMinutes(), 1),
80	                            now);
81	                    repository.insertRevision(equipmentId, req.readingId(), 1,
82	                            req.cumulativeMinutes(), req.requestId(), now);
83	                    repository.incrementVersion(equipmentId);
84	                    return new ReadingResponse(equipmentId, req.readingId(), req.sampledAt(),
85	                            req.cumulativeMinutes(), 1, false, equipment.version() + 1);
86	                });
87	    }
88	
89	    // ---------- 修订读数 ----------
90	
91	    @Transactional
92	    public ReadingResponse reviseReading(String equipmentId, String readingId, ReviseReadingRequest req) {
93	        Equipment equipment = lockEquipment(equipmentId);
94	        String fingerprint = equipmentId + "|" + readingId + "|" + req.cumulativeMinutes()
95	                + "|" + req.expectedVersion();
96	        return idempotency.execute(req.requestId(), "REVISE_READING", fingerprint,
97	                ReadingResponse.class, () -> {
98	                    checkVersion(equipment, req.expectedVersion());
99	                    Reading reading = repository.findReading(equipmentId, readingId)
100	                            .orElseThrow(() -> ApiException.notFound("READING_NOT_FOUND",
101	                                    "读数不存在：" + readingId));
102	                    if (repository.existsMaintenanceAnchoringReading(equipmentId, readingId)) {
103	                        throw ApiException.conflict("READING_ANCHORED",
104	                                "读数已作为历史保养锚点，不可修订：" + readingId);
105	                    }
106	                    checkMonotonic(equipmentId, reading.sampledAt(), req.cumulativeMinutes());
107	                    int newRevisionNo = reading.revisionNo() + 1;
108	                    Instant now = clock.instant();
109	                    repository.updateReadingValue(equipmentId, readingId, req.cumulativeMinutes(),
110	                            newRevisionNo, now);
111	                    repository.insertRevision(equipmentId, readingId, newRevisionNo,
112	                            req.cumulativeMinutes(), req.requestId(), now);
113	                    repository.incrementVersion(equipmentId);
114	                    return new ReadingResponse(equipmentId, readingId, reading.sampledAt(),
115	                            req.cumulativeMinutes(), newRevisionNo, false, equipment.version() + 1);
116	                });
117	    }
118	
119	    // ---------- 完成保养 ----------
120	
121	    @Transactional
122	    public MaintenanceResponse completeMaintenance(String equipmentId, CompleteMaintenanceRequest req) {
123	        Equipment equipment = lockEquipment(equipmentId);
124	        String fingerprint = equipmentId + "|" + req.readingId() + "|" + req.anchorRevisionNo()
125	                + "|" + req.expectedVersion();
126	        return idempotency.execute(req.requestId(), "COMPLETE_MAINTENANCE", fingerprint,
127	                MaintenanceResponse.class, () -> {
128	                    checkVersion(equipment, req.expectedVersion());
129	                    Reading anchor = repository.findReading(equipmentId, req.readingId())
130	                            .orElseThrow(() -> ApiException.notFound("READING_NOT_FOUND",
131	                                    "锚点读数不存在：" + req.readingId()));
132	                    if (anchor.revisionNo() != req.anchorRevisionNo()) {
133	                        throw ApiException.conflict("ANCHOR_REVISION_CONFLICT",
134	                                "锚点修订号与读数当前修订号不一致：期望 " + req.anchorRevisionNo()
135	                                        + "，当前 " + anchor.revisionNo());
136	                    }
137	                    Optional<MaintenanceRecord> last = repository.findLastMaintenance(equipmentId);
138	                    if (last.isPresent() && !anchor.sampledAt().isAfter(last.get().anchorSampledAt())) {
139	                        throw ApiException.unprocessable("ANCHOR_TIME_NOT_LATER",
140	                                "保养锚点时间必须晚于上次保养锚点时间");
141	                    }
142	                    Instant now = clock.instant();
143	                    long maintenanceId = repository.insertMaintenance(equipmentId, req.readingId(),
144	                            req.anchorRevisionNo(), anchor.sampledAt(), anchor.cumulativeMinutes(),
145	                            req.requestId(), now);
146	                    repository.incrementVersion(equipmentId);
147	                    return new MaintenanceResponse(maintenanceId, equipmentId, req.readingId(),
148	                            req.anchorRevisionNo(), anchor.sampledAt(), anchor.cumulativeMinutes(),
149	                            now, equipment.version() + 1);
150	                });
151	    }
152	
153	    // ---------- 查询 ----------
154	
155	    @Transactional(readOnly = true)
156	    public StatusResponse getStatus(String equipmentId) {
157	        Equipment equipment = repository.findEquipment(equipmentId)
158	                .orElseThrow(() -> equipmentNotFound(equipmentId));
159	        Optional<Reading> latest = repository.findLatestReading(equipmentId);
160	        Optional<MaintenanceRecord> last = repository.findLastMaintenance(equipmentId);
161	        long latestCumulative = latest.map(Reading::cumulativeMinutes).orElse(0L);
162	        long anchorCumulative = last.map(MaintenanceRecord::anchorCumulativeMinutes).orElse(0L);
163	        long runMinutes = latestCumulative - anchorCumulative;
164	        String status = runMinutes >= equipment.maintenancePeriodMinutes() ? "DUE" : "OK";
165	        return new StatusResponse(equipmentId, equipment.version(), equipment.maintenancePeriodMinutes(),
166	                latest.map(Reading::sampledAt).orElse(null), latestCumulative,
167	                last.map(MaintenanceRecord::anchorSampledAt).orElse(null), anchorCumulative,
168	                runMinutes, status);
169	    }
170	
171	    @Transactional(readOnly = true)
172	    public List<ReadingResponse> listReadings(String equipmentId) {
173	        Equipment equipment = repository.findEquipment(equipmentId)
174	                .orElseThrow(() -> equipmentNotFound(equipmentId));
175	        return repository.listReadings(equipmentId).stream()
176	                .map(reading -> new ReadingResponse(equipmentId, reading.readingId(), reading.sampledAt(),
177	                        reading.cumulativeMinutes(), reading.revisionNo(),
178	                        repository.existsMaintenanceAnchoringReading(equipmentId, reading.readingId()),
179	                        equipment.version()))
180	                .toList();
181	    }
182	
183	    @Transactional(readOnly = true)
184	    public List<RevisionView> listRevisions(String equipmentId, String readingId) {
185	        repository.findEquipment(equipmentId).orElseThrow(() -> equipmentNotFound(equipmentId));
186	        repository.findReading(equipmentId, readingId)
187	                .orElseThrow(() -> ApiException.notFound("READING_NOT_FOUND", "读数不存在：" + readingId));
188	        return repository.listRevisions(equipmentId, readingId).stream()
189	                .map(row -> new RevisionView(row.revisionNo(), row.cumulativeMinutes(),
190	                        row.requestId(), row.createdAt()))
191	                .toList();
192	    }
193	
194	    @Transactional(readOnly = true)
195	    public List<MaintenanceResponse> listMaintenances(String equipmentId) {
196	        repository.findEquipment(equipmentId).orElseThrow(() -> equipmentNotFound(equipmentId));
197	        return repository.listMaintenances(equipmentId).stream()
198	                .map(record -> new MaintenanceResponse(record.maintenanceId(), equipmentId,
199	                        record.readingId(), record.anchorRevisionNo(), record.anchorSampledAt(),
200	                        record.anchorCumulativeMinutes(), record.completedAt(), 0L))
201	                .toList();
202	    }
203	
204	    // ---------- 内部规则 ----------
205	
206	    private Equipment lockEquipment(String equipmentId) {
207	        return repository.findEquipmentForUpdate(equipmentId)
208	                .orElseThrow(() -> equipmentNotFound(equipmentId));
209	    }
210	
211	    private ApiException equipmentNotFound(String equipmentId) {
212	        return ApiException.notFound("EQUIPMENT_NOT_FOUND", "设备不存在：" + equipmentId);
213	    }
214	
215	    private void checkVersion(Equipment equipment, long expectedVersion) {
216	        if (equipment.version() != expectedVersion) {
217	            throw ApiException.conflict("VERSION_CONFLICT",
218	                    "设备版本冲突：期望 " + expectedVersion + "，当前 " + equipment.version());
219	        }
220	    }
221	
222	    /** 单调性校验：新值须同时不早于前相邻读数、不晚于后相邻读数（按采样时刻排序）。 */
223	    private void checkMonotonic(String equipmentId, Instant sampledAt, long cumulativeMinutes) {
224	        Optional<Reading> prev = repository.findPrevReading(equipmentId, sampledAt);
225	        if (prev.isPresent() && cumulativeMinutes < prev.get().cumulativeMinutes()) {
226	            throw ApiException.unprocessable("READING_ORDER_VIOLATION",
227	                    "累计工时小于前一条读数（" + prev.get().cumulativeMinutes() + "），违反单调不减约束");
228	        }
229	        Optional<Reading> next = repository.findNextReading(equipmentId, sampledAt);
230	        if (next.isPresent() && cumulativeMinutes > next.get().cumulativeMinutes()) {
231	            throw ApiException.unprocessable("READING_ORDER_VIOLATION",
232	                    "累计工时大于后一条读数（" + next.get().cumulativeMinutes() + "），违反单调不减约束");
233	        }
234	    }
235	}
