25	import com.example.starter.maintenance.service.EquipmentService;
26	
27	/**
28	 * 设备工时保养判定 API。不连接真实设备，读数由调用方登记/补录。
29	 */
30	@RestController
31	@RequestMapping("/api/equipment")
32	public class EquipmentController {
33	
34	    private final EquipmentService service;
35	
36	    public EquipmentController(EquipmentService service) {
37	        this.service = service;
38	    }
39	
40	    /** 登记设备：保养周期（分钟）为正整数，登记后不可修改；初始版本 1、累计工时 0。 */
41	    @PostMapping
42	    @ResponseStatus(HttpStatus.CREATED)
43	    public EquipmentResponse register(@Valid @RequestBody RegisterEquipmentRequest req) {
44	        return service.register(req);
45	    }
46	
47	    /** 新增工时读数（允许补录历史）；按采样时刻排序后累计分钟须单调不减，否则 422。 */
48	    @PostMapping("/{equipmentId}/readings")
49	    @ResponseStatus(HttpStatus.CREATED)
50	    public ReadingResponse addReading(@PathVariable String equipmentId,
51	                                      @Valid @RequestBody AddReadingRequest req) {
52	        return service.addReading(equipmentId, req);
53	    }
54	
55	    /** 修订读数：只改累计分钟、不改采样时刻；作为历史保养锚点的读数返回 409。 */
56	    @PostMapping("/{equipmentId}/readings/{readingId}/revisions")
57	    @ResponseStatus(HttpStatus.CREATED)
58	    public ReadingResponse reviseReading(@PathVariable String equipmentId,
